// Mock live events using real training data
export const mockLiveEvents = realTrainingEvents.slice(0, 20).map((event, index) => ({
  id: `real-${index + 1}`,
  type: event.type,
  minute: event.minute,
  player: event.player,
  team: event.team,
  description: event.description
}));
